import org.apache.axis2.engine.AxisConfiguration;
import org.apache.axiom.om.OMElement;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.MockedStatic;

class ConsultaCadastroTests {

    private CadConsultaCadastro4Stub stub;
    private CadConsultaCadastro4Stub.NfeDadosMsg nfeDadosMsg;

    @BeforeEach
    void setUp() throws AxisFault {
        stub = new CadConsultaCadastro4Stub("https://nfe.sefaz.ms.gov.br/ws/CadConsultaCadastro4");
        nfeDadosMsg = mock(CadConsultaCadastro4Stub.NfeDadosMsg.class);
    }

    @Test
    void testConsultaCadastroWithNullInput() {
        assertThrows(IllegalArgumentException.class, () -> {
            stub.consultaCadastro(null);
        });
    }

    @Test
    void testConstructorWithConfigurationContext() throws AxisFault {
        ConfigurationContext configContext = mock(ConfigurationContext.class);
        AxisConfiguration axisConfiguration = mock(AxisConfiguration.class);
        when(configContext.getAxisConfiguration()).thenReturn(axisConfiguration);
        when(axisConfiguration.getTransportsIn()).thenReturn(new java.util.HashMap<>());

        assertDoesNotThrow(() -> {
            new CadConsultaCadastro4Stub(configContext, "https://test.endpoint");
        });
    }

    @Test
    void testConstructorWithConfigurationContextAndListener() throws AxisFault {
        ConfigurationContext configContext = mock(ConfigurationContext.class);
        AxisConfiguration axisConfiguration = mock(AxisConfiguration.class);
        when(configContext.getAxisConfiguration()).thenReturn(axisConfiguration);
        when(axisConfiguration.getTransportsIn()).thenReturn(new java.util.HashMap<>());

        assertDoesNotThrow(() -> {
            new CadConsultaCadastro4Stub(configContext, "https://test.endpoint", true);
        });
    }

    @Test
    void testDefaultConstructor() {
        assertDoesNotThrow(() -> new CadConsultaCadastro4Stub());
    }

    @Test
    void testConsultaCadastroSuccess() throws Exception {
        try (MockedStatic<ServiceClient> mockedServiceClient = mockStatic(ServiceClient.class)) {
            ServiceClient serviceClient = mock(ServiceClient.class);
            mockedServiceClient.when(() -> ServiceClient.class.getDeclaredConstructor(
                    ConfigurationContext.class, 
                    org.apache.axis2.description.AxisService.class))
                    .thenReturn(serviceClient);

            when(serviceClient.sendReceive(any())).thenReturn(createSuccessfulResponse());
            when(nfeDadosMsg.getOMElement(any(), any())).thenReturn(mock(OMElement.class));

            CadConsultaCadastro4Stub.NfeResultMsg result = stub.consultaCadastro(nfeDadosMsg);

            assertNotNull(result);
        }
    }

    @Test
    void testConsultaCadastroRemoteException() throws Exception {
        try (MockedStatic<ServiceClient> mockedServiceClient = mockStatic(ServiceClient.class)) {
            ServiceClient serviceClient = mock(ServiceClient.class);
            mockedServiceClient.when(() -> ServiceClient.class.getDeclaredConstructor(
                    ConfigurationContext.class, 
                    org.apache.axis2.description.AxisService.class))
                    .thenReturn(serviceClient);

            when(serviceClient.sendReceive(any())).thenThrow(new RemoteException("SOAP Fault"));
            when(nfeDadosMsg.getOMElement(any(), any())).thenReturn(mock(OMElement.class));

            assertThrows(RemoteException.class, () -> {
                stub.consultaCadastro(nfeDadosMsg);
            });
        }
    }

    private OMElement createSuccessfulResponse() {
        org.apache.axiom.om.OMFactory factory = org.apache.axiom.om.OMAbstractFactory.getOMFactory();
        OMElement response = factory.createOMElement("NfeResultMsg", null);
        OMElement result = factory.createOMElement("result", null);
        result.setText("SUCCESS");
        response.addChild(result);
        return response;
    }
}

